fn e_hat_couples_force_and_moment_through_the_body_extent_in_binary64() {
    assert_eq!(e_hat([1.0, 8.0], 0.0), [1.0, 8.0]);
    assert_eq!(e_hat([1.0, 8.0], 2.0), [4.0, 8.0]);
    assert_eq!(e_hat([5.0, 8.0], 2.0), [5.0, 10.0]);
