fn sd_g5_charge_boundaries_at_p_256_and_p_512_and_the_translation_row() {
    // (d) for the candidate p = 256 (P = 512: 60·ê·2^-P) and p = 512
    // (P = 1024: 2^-86·M_q, M_q = 1 here, the floor Φ below it).
    let layout = force_row();
