        assert_eq!(tok(&rhs[a]), tok(&s.round(&mut c).unwrap()), "row {i}");
        if !rhs[a].fits_precision(53) {
            wider += 1;
        }
    }
    // Entries wider than binary64: the rhs is never rounded back to 53 bits.
    assert!(wider >= 2, "{wider}");
