structural::retained::assemble::tests::t.excerpt:
fn the_duplicate_operand_entry_is_one_exact_sum_where_a_sequential_fold_loses_the_weak_member() {
    // DUPLICATE: members 1 (0–1) and 3 (1–2) are identical and collinear, so
    // their contributions to K(uy_1, rz_1) cancel exactly; member 2, 2^-300 as
    // stiff, sorts between them in the canonical (id) order. Entry (7, 11) =
    // node 1's (uy, rz).
    let m = models::model("DUPLICATE");
    let source = m.source();
    assert_eq!(
        source.members().iter().map(|m| m.id).collect::<Vec<_>>(),
        vec![1, 2, 3],
        "the weak member sits between the two"
    );
    fn check<const L: usize>(source: &PrimitiveSource, p: u32, fold_loses: bool)
    where
        Wide<L>: SupportedWidth,
    {
        let (structure, k, members) = assembled::<L>(source, p);
        let entry = k[structure.pattern.find(7, 11).unwrap()];
        // The contributions, in canonical order (member 1: node 1 is its j
        // end; members 2 and 3: node 1 is their i end).
        let parts = [
            members[0].ke(7, 11),
            members[1].ke(1, 5),
            members[2].ke(1, 5),
        ];
        let mut exact = ExactWideSum::new();
        for x in parts {
            exact.add_wide(x, false).unwrap();
        }
        let mut c: WideContext<L> = ctx::<L>(p);
        assert_eq!(tok(&entry), tok(&exact.round(&mut c).unwrap()), "p {p}");
        assert!(!entry.is_zero(), "p {p}: the weak member is kept");
        let folded = {
            let s = c.add(parts[0], parts[1]).unwrap();
            c.add(&s, parts[2]).unwrap()
        };
        assert_eq!(folded.is_zero(), fold_loses, "p {p}: sequential fold");
    }
    check::<4>(&source, 128, true);
    check::<4>(&source, 256, true);
    check::<8>(&source, 512, false);
}

structural::retained::recover::tests::a_.excerpt:
fn a_recovered_action_is_one_exact_expansion_where_a_sequential_fold_loses_a_term() {
    // D16's recovery half. A member along (1,2,2)/3 whose node i moves by
    // u_i = (2, 2^-200, −1) and node j not at all: e_x·u_i = 2/3 − 2/3 +
    // (2/3)·2^-200 at p (e_x = (1/3, 2/3, 2/3) rounded at p, 2·fl(1/3) =
    // fl(2/3) exactly). A sequential fold in the code's order adds the tiny
    // term to 2/3 first and loses it, so the axial force would be 0; its true
    // value is −(EA/L)·(2/3)·2^-200.
    let dof = |node, c| Dof {
        node,
        component: Component::from_index(c),
    };
    let tiny = f64::from_bits(0x3370_0000_0000_0000); // 2^-200
    let mut parts = SourceParts {
        nodes: vec![[0.0, 0.0, 0.0], [1.0, 2.0, 2.0]],
        members: vec![StraightMember {
            id: 1,
            node_i: 0,
            node_j: 1,
            elastic_modulus: 200e9,
            shear_modulus: 80e9,
            area: 6e-3,
            second_moment_y: 2.7e-5,
            second_moment_z: 2.7e-5,
            torsion_constant: 5.4e-5,
            y_reference: [1.0, 0.0, 0.0],
        }],
        ..Default::default()
    };
    for (c, v) in [2.0, tiny, -1.0, 0.0, 0.0, 0.0].into_iter().enumerate() {
        parts.constraints.push(Constraint {
            dof: dof(0, c),
            value: v,
        });
        parts.constraints.push(Constraint {
            dof: dof(1, c),
            value: 0.0,
        });
    }
    let source = PrimitiveSource::new(parts).unwrap();
    let layout = layout(&source);
    let structure = Structure::new(&source).unwrap();
    let guard = StageGuard::unlimited();
    let mut c = support::ctx::<4>(128);
    let mut sum = ExactWideSum::new();
    let members = form_members(&mut c, &mut sum, &guard, &source).unwrap();
    let directional = form_directional(&mut c, &mut sum, &source).unwrap();
    let k = assemble(
        &mut c,
        &mut sum,
        &guard,
        &source,
        &structure,
        &members,
        &directional,
    )
    .unwrap();
    let ledger = RetainedLedger::from_source(&source).unwrap();
    let u: Vec<Wide<4>> = (0..source.dof_count())
        .map(|g| support::lift::<4>(source.constraint(g).unwrap()))
        .collect();
    let recovered = recover(
        &mut c,
        &mut sum,
        &guard,
        &source,
        &layout,
        &structure,
        &k,
        &members,
        &directional,
        &ledger,
        &u,
    )
    .unwrap();
    let index = layout
        .iter()
        .position(|m| {
            m.id == QuantityId::EndAction {
                member: 1,
                end: End::J,
                component: Component::Ux,
            }
        })
        .unwrap();
    let n = publish_value(&recovered.values[index]).value().unwrap();
    let exact = -(200e9 * 6e-3 / 3.0) * (2.0 / 3.0) * tiny;
    assert!(n != 0.0);
    assert!(
        (n - exact).abs() <= 1e-12 * exact.abs(),
        "{n:e} vs {exact:e}"
    );
    // The code-order fold of e_x·u_i at p loses the term.
    let ex = &members[0].axes[0];
    let mut folded = Wide::<4>::ZERO;
    for kk in 0..3 {
        let t = c.mul(&ex[kk], &u[kk]).unwrap();
        folded = c.add(&folded, &t).unwrap();
    }
    assert!(folded.is_zero());
}

