    // U4: σ_c = 2^-9000 (a σ no estimate gives): σ′'s subtraction spans more
    // than 8,128 bits, so S_c is refused and not retried, and B_c = Uc_c.
    let mut first = Vec::new();
    let mut rows = Vec::new();
    let mut blk = Vec::new();
